function dayKey(date=new Date()){return date.getFullYear()+"-"+String(date.getMonth()+1).padStart(2,"0")+"-"+String(date.getDate()).padStart(2,"0")}
function dayWordCount(key=dayKey()){const value=progress.days[key];return typeof value==="number"?value:(Array.isArray(value?.words)?value.words.length:(value?.count||0))}
function recordActivity(wordId){const key=dayKey();let entry=progress.days[key];if(typeof entry==="number")entry={count:entry,words:[]};else if(!entry||typeof entry!=="object"||Array.isArray(entry))entry={count:0,words:[]};entry.count=(entry.count||0)+1;if(!Array.isArray(entry.words))entry.words=[];if(wordId!==undefined&&wordId!==null&&!entry.words.includes(String(wordId)))entry.words.push(String(wordId));progress.days[key]=entry;progress.lastActive=key;saveProgress()}
function pFor(word){return progress.words[String(word.id)]||{saved:false,known:false,interval:0,repetitions:0,due:0,seen:0}}
function isDue(word){const p=pFor(word);return !p.due||p.due<=Date.now()}
function saveWordState(word,patch){const id=String(word.id);progress.words[id]={...pFor(word),...patch,_updatedAt:Date.now()};progress.reviewCount+=(patch.seen!==undefined?1:0);recordActivity(word.id)}
function getDerivedWordSets(){const minute=Math.floor(Date.now()/60000);if(!derivedWordSets||derivedWordSetsRevision!==progressRevision||derivedWordSets.minute!==minute){const known=[],saved=[],due=[],now=Date.now();for(const w of words){const p=pFor(w);if(p.known)known.push(w);if(p.saved)saved.push(w);if(!p.due||p.due<=now)due.push(w)}derivedWordSets={known,saved,due,minute};derivedWordSetsRevision=progressRevision}return derivedWordSets}
function dueWords(){return getDerivedWordSets().due}
function savedWords(){return getDerivedWordSets().saved}
function knownWords(){return getDerivedWordSets().known}
function streak(){let n=0,d=new Date();if(!progress.days[dayKey(d)])d.setDate(d.getDate()-1);while(progress.days[dayKey(d)]){n++;d.setDate(d.getDate()-1)}return n}
function toast(message){$("toast").textContent=message;$("toast").classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>$("toast").classList.remove("show"),2500)}
function setDbStatus(mode,msg){const el=$("dbStatus");el.className="connection "+mode;el.querySelector("span").textContent=msg}
function normaliseWord(w){w=w&&typeof w==="object"&&!Array.isArray(w)?w:{};return{...w,word:String(w.word||""),meaning_fa:String(w.meaning_fa||""),examples_de:Array.isArray(w.examples_de)?w.examples_de:[],extra_examples_de:Array.isArray(w.extra_examples_de)?w.extra_examples_de:[],example_de:String(w.example_de||"")}} function rebuildWordIndexes(){wordById=new Map(words.map(w=>[String(w.id),w]));wordSearchIndex=new Map(words.map(w=>[String(w.id),(w.word+" "+w.meaning_fa+" "+w.examples_de.join(" ")+" "+w.extra_examples_de.join(" ")+" "+w.example_de+" "+(w.thematic_group||"")).toLocaleLowerCase()]))}
