async function loadWords(){let cached=[];try{const stored=JSON.parse(localStorage.getItem(CACHE_KEY)||"[]");if(Array.isArray(stored))cached=stored.filter(w=>w&&typeof w==="object"&&!Array.isArray(w)&&w.id!==undefined&&w.id!==null)}catch{}if(cached.length){words=cached.map(normaliseWord);rebuildWordIndexes();renderAll()}setDbStatus("loading",cached.length?"به‌روزرسانی واژگان":"دریافت واژگان");try{const chunks=await Promise.all([0,1000,2000,3000].map(fetchWordPage));for(let offset=4000;chunks[chunks.length-1]?.length===1000;offset+=1000){const page=await fetchWordPage(offset);chunks.push(page);if(page.length<1000)break}const fresh=chunks.flat().filter(Boolean).map(normaliseWord);if(!fresh.length)throw new Error("جدول واژگان هنوز خالی است");words=fresh;rebuildWordIndexes();try{localStorage.setItem(CACHE_KEY,JSON.stringify(words))}catch{}setDbStatus("ok",faNum(words.length)+" واژه متصل");renderAll()}catch(err){if(words.length){setDbStatus("","حالت آفلاین");if(!cached.length)toast("از نسخه‌ی ذخیره‌شده‌ی واژگان استفاده می‌شود.");console.warn("Vocabulary refresh failed; using cached data.",err);return}setDbStatus("","اتصال ناموفق");$("statTotal").textContent="—";$("wordList").innerHTML='<div class="empty">دیتابیس واژگان در دسترس نیست. تنظیمات Supabase و سیاست دسترسی خواندن را بررسی کن.</div>';console.error(err)}}
