const TYPE_LABELS={Nomen:"اسم",Verb:"فعل",Adjektiv:"صفت",Adverb:"قید",Präposition:"حرف اضافه",Konjunktion:"حرف ربط",Pronomen:"ضمیر",Determinativ:"تعیین‌گر",Partikel:"ذرهٔ دستوری",Interjektion:"واژهٔ ندایی",Numerale:"عددواژه",Wortgruppe:"عبارت / گروه واژگانی",Wortbildungselement:"جزء واژه‌سازی",Verbpartikel:"جزء فعلی جداشدنی",Operator:"عملگر ریاضی",Abkürzung:"مخفف"};
