function renderDictionary(){const filtered=filteredWords(),pageSize=30;dictPage=Math.min(dictPage,Math.max(0,Math.ceil(filtered.length/pageSize)-1));const start=dictPage*pageSize,page=filtered.slice(start,start+pageSize);$("wordList").innerHTML=page.length?page.map(rowHtml).join(""):'<div class="empty">واژه‌ای با این مشخصات پیدا نشد.</div>';$("listCount").textContent=filtered.length?faNum(start+1)+" تا "+faNum(Math.min(start+pageSize,filtered.length))+" از "+faNum(filtered.length)+" واژه":"۰ نتیجه";$("prevPage").disabled=dictPage===0;$("nextPage").disabled=start+pageSize>=filtered.length}
