function openDetail(w){if(!w)return;if(!document.querySelector(".detail-overlay.open,.command-overlay.open,.auth-overlay.open"))modalReturnFocus=document.activeElement;const p=pFor(w),examples=[...w.examples_de,...w.extra_examples_de];if(!examples.length&&w.example_de)examples.push(w.example_de);const meta=[];if(w.case_info)meta.push("حالت: "+w.case_info);if(w.preposition)meta.push("حرف اضافه: "+w.preposition);if(w.thematic_group)meta.push("گروه: "+w.thematic_group);if(w.pdf_page)meta.push("صفحه‌ی منبع: "+w.pdf_page);if(w.equivalent)meta.push("معادل: "+w.equivalent);$("detailModal").innerHTML='<div class="modal-top"><span class="tag '+typeClass(w.word_type)+'">'+safe(typeLabel(w.word_type))+'</span><button class="icon-button" id="closeDetail" aria-label="بستن">'+svg("close")+'</button></div><div class="modal-word">'+safe(w.word)+'</div><div class="modal-meaning">'+safe(w.meaning_fa||"معنی ثبت نشده")+'</div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn-secondary" id="speakWord">'+svg("volume")+' تلفظ آلمانی</button><button class="btn-secondary" id="toggleSavedDetail">'+svg("bookmark")+(p.saved?"حذف از نشان‌شده‌ها":"ذخیره‌ی واژه")+'</button><button class="btn-primary" id="practiceDetail">'+svg("bolt")+' تمرین این واژه</button></div>'+(examples.length?'<div class="modal-label">جمله‌های نمونه</div>'+examples.map(ex=>'<div class="modal-example">'+safe(ex)+'</div>').join(""):'<div class="modal-label">برای این واژه مثال ثبت نشده است.</div>')+(meta.length?'<div class="modal-meta">'+meta.map(m=>'<span>'+safe(m)+'</span>').join("")+'</div>':'');$("detailOverlay").classList.add("open");$("detailOverlay").setAttribute("aria-hidden","false");$("closeDetail").onclick=()=>closeModal("detailOverlay");setTimeout(()=>$("closeDetail")?.focus(),0);$("speakWord").onclick=()=>speak(w.word);$("toggleSavedDetail").onclick=()=>{toggleSaved(w);openDetail(w)};$("practiceDetail").onclick=()=>{closeModal("detailOverlay");startSession("flash",[w])}}
