function loadDaily(){const base={cursor:0,studied:[],days:{},mode:"learn",reviewQueue:[],reviewIndex:0,reviewAnswers:[],reviewCorrect:0,lastCheckpoint:0};try{const saved=JSON.parse(localStorage.getItem(DAILY_KEY)||"null");if(!saved||typeof saved!=="object")return base;return{...base,...saved,cursor:Number.isInteger(saved.cursor)&&saved.cursor>=0?saved.cursor:0,studied:Array.isArray(saved.studied)?saved.studied.map(String):[],days:saved.days&&typeof saved.days==="object"?saved.days:{},reviewQueue:Array.isArray(saved.reviewQueue)?saved.reviewQueue:[],reviewAnswers:Array.isArray(saved.reviewAnswers)?saved.reviewAnswers:[]}}catch{return base}}
function saveDaily(){try{localStorage.setItem(DAILY_KEY,JSON.stringify(daily))}catch(err){console.warn("Could not persist daily-learning state",err)}markLocalProgressDirty();queueCloudSync()}
function shuffleItems(items){const copy=[...items];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy}
function dailyTodayCount(){const today=daily.days[dayKey()];return Array.isArray(today)?today.length:0}
function beginDailyReview(){const eligible=daily.studied.map(id=>wordById.get(String(id))).filter(w=>w&&String(w.meaning_fa||"").trim());const count=Math.min(eligible.length,Math.round(eligible.length*.6));const chosen=shuffleItems(eligible).slice(0,count);daily.reviewQueue=chosen.map(w=>{const targetMeaning=String(w.meaning_fa).trim(),pool=words.filter(x=>String(x.id)!==String(w.id)&&String(x.meaning_fa||"").trim()&&String(x.meaning_fa).trim()!==targetMeaning),distractors=[];const seenIds=new Set([String(w.id)]);for(let tries=0;tries<Math.min(80,words.length*2)&&distractors.length<3;tries++){const candidate=words[Math.floor(Math.random()*words.length)];if(candidate&&String(candidate.meaning_fa||"").trim()&&String(candidate.meaning_fa).trim()!==targetMeaning&&!seenIds.has(String(candidate.id))){distractors.push(candidate);seenIds.add(String(candidate.id))}}if(distractors.length<Math.min(3,pool.length)){for(const candidate of shuffleItems(pool)){if(!seenIds.has(String(candidate.id))){distractors.push(candidate);seenIds.add(String(candidate.id));if(distractors.length===3)break}}}return{id:String(w.id),options:shuffleItems([w,...distractors]).map(x=>String(x.id))}});daily.reviewIndex=0;daily.reviewAnswers=Array(count).fill(null);daily.reviewCorrect=0;daily.lastCheckpoint=daily.studied.length;daily.mode="review";saveDaily();renderDaily()}
function renderDaily(){const content=$("dailyContent");if(!$("dailyCounter")||!content)return;const total=words.length,position=Math.min(daily.cursor,total),today=dailyTodayCount();$("dailyCounter").textContent=faNum(daily.studied.length)+" / "+faNum(total)+" واژه خوانده‌شده";$("dailyProgress").style.width=(total?Math.min(100,Math.round(position/total*100)):0)+"%";$("dailyTodayCount").textContent="امروز: "+faNum(today)+" واژه";$("dailyCycle").textContent=daily.mode==="review"?"مرور خودکار":daily.mode==="reviewDone"?"پایان مرور":"یادگیری";if(!total){content.innerHTML='<div class="empty">واژه‌ها هنوز از دیتابیس بارگذاری نشده‌اند.</div>';return}if(daily.mode==="review"){renderDailyReview();return}if(daily.mode==="reviewDone"){content.innerHTML='<div class="daily-finish"><div class="daily-finish-mark">'+svg("check")+'</div><h2>مرور این مرحله تمام شد</h2><p>'+faNum(daily.reviewCorrect)+' پاسخ درست از '+faNum(daily.reviewQueue.length)+' سؤال. اکنون به واژه‌ی بعدی برگرد.</p><button class="btn-primary" id="dailyContinue">'+svg("arrow")+' ادامه‌ی یادگیری</button></div>';$("dailyContinue").onclick=()=>{daily.mode="learn";saveDaily();renderDaily()};return}if(position>=total){content.innerHTML='<div class="daily-finish"><div class="daily-finish-mark">'+svg("spark")+'</div><h2>همه‌ی واژه‌های دیتابیس را خوانده‌ای</h2><p>'+faNum(daily.studied.length)+' واژه در بخش یادگیری روزانه ثبت شده است. برای ادامه، از واژه‌نامه استفاده کن.</p><button class="btn-secondary" id="dailyGoDictionary">رفتن به واژه‌نامه</button></div>';$("dailyGoDictionary").onclick=()=>changeView("dictionary");return}const w=words[position],id=String(w.id),already=daily.studied.includes(id);const rawExamples=[w.example_de,...w.examples_de,...w.extra_examples_de].map(x=>String(x??"").trim()).filter(Boolean);const examples=[...new Set(rawExamples)];const meta=[["نوع واژه",typeLabel(w.word_type)],["حالت دستوری",w.case_info],["حرف اضافه",w.preposition],["معادل ثبت‌شده",w.equivalent],["گروه موضوعی",w.thematic_group],["شماره منبع",w.source_number],["کد رکورد",w.record_code],["بخش منبع",w.record_section],["صفحه PDF",w.pdf_page]].filter(([label,value])=>value!==null&&value!==undefined&&String(value).trim()!=="");content.innerHTML='<article class="daily-word-card"><div class="daily-word-top"><span class="tag '+typeClass(w.word_type)+'">'+safe(typeLabel(w.word_type))+'</span><span class="daily-page-label">واژه‌ی '+faNum(position+1)+' از '+faNum(total)+'</span></div><div class="daily-word-title" lang="de">'+safe(w.word)+'</div><div class="daily-word-meaning">'+safe(w.meaning_fa||"معنی فارسی در دیتابیس ثبت نشده است.")+'</div><div class="daily-word-actions"><button class="btn-secondary" id="dailySpeak">'+svg("volume")+' شنیدن تلفظ</button><button class="btn-secondary" id="dailyBookmark">'+svg("bookmark")+(pFor(w).saved?" حذف نشان":" نشان‌کردن واژه")+'</button></div><section class="daily-info-section"><h3>اطلاعات واژه</h3><div class="daily-info-grid">'+(meta.length?meta.map(([label,value])=>'<div class="daily-info-item"><span>'+safe(label)+'</span><strong>'+safe(value)+'</strong></div>').join(""):'<div class="daily-info-item"><span>اطلاعات تکمیلی</span><strong>جزئیات بیشتری در این رکورد ثبت نشده است.</strong></div>')+'</div></section><section class="daily-info-section"><h3>جمله‌های نمونه</h3>'+(examples.length?'<div class="daily-examples">'+examples.map((ex,i)=>'<div class="daily-example"><span>'+faNum(i+1)+'</span><p lang="de" dir="ltr">'+safe(ex)+'</p></div>').join("")+'</div>':'<div class="daily-no-example">برای این واژه جمله‌ی نمونه‌ای در دیتابیس ثبت نشده است.</div>')+'</section><div class="daily-word-footer"><button class="btn-secondary" id="dailyPrev" '+(position===0?'disabled':'')+'>'+svg("arrow")+' واژه‌ی قبلی</button><span>'+(already?"این واژه قبلاً خوانده شده":"پس از مطالعه، واژه‌ی بعدی را باز کن")+'</span><button class="btn-primary" id="dailyNext">'+(already?'واژه‌ی بعدی':'خواندم؛ واژه‌ی بعدی')+' '+svg("arrow")+'</button></div></article>';$("dailySpeak").onclick=()=>speak(w.word);$("dailyBookmark").onclick=()=>{toggleSaved(w);renderDaily()};$("dailyPrev").onclick=()=>{if(daily.cursor>0){daily.cursor--;saveDaily();renderDaily()}};$("dailyNext").onclick=()=>{if(!daily.studied.includes(id)){daily.studied.push(id);if(!Array.isArray(daily.days[dayKey()]))daily.days[dayKey()]=[];if(!daily.days[dayKey()].includes(id))daily.days[dayKey()].push(id);recordActivity(w.id)}daily.cursor=Math.min(total,daily.cursor+1);if(daily.studied.length>0&&daily.studied.length%10===0&&daily.lastCheckpoint<daily.studied.length){beginDailyReview();return}saveDaily();renderDaily()}}
function renderDailyReview(){const content=$("dailyContent"),item=daily.reviewQueue[daily.reviewIndex];if(!item){daily.mode="reviewDone";saveDaily();renderDaily();return}const w=wordById.get(String(item.id));if(!w){daily.reviewIndex++;saveDaily();renderDaily();return}const answer=daily.reviewAnswers[daily.reviewIndex];content.innerHTML='<article class="daily-word-card daily-review-card"><div class="daily-word-top"><span class="daily-review-label">مرور واژه‌های خوانده‌شده</span><span class="daily-page-label">سؤال '+faNum(daily.reviewIndex+1)+' از '+faNum(daily.reviewQueue.length)+'</span></div><div class="daily-review-progress"><span style="width:'+Math.round((daily.reviewIndex+(answer?1:0))/Math.max(1,daily.reviewQueue.length)*100)+'%"></span></div><div class="daily-question-kicker">WAS BEDEUTET DAS?</div><div class="daily-word-title" lang="de">'+safe(w.word)+'</div><p class="daily-question-text">معنی فارسی این واژه چیست؟</p><div class="daily-review-options">'+item.options.map(id=>{const option=wordById.get(String(id));if(!option)return"";const selected=answer&&String(answer.selectedId)===String(id);const correct=String(id)===String(w.id);const cls=answer&&correct?"correct":answer&&selected&&!answer.correct?"wrong":"";return'<button class="daily-review-option '+cls+'" data-daily-option="'+safe(id)+'" '+(answer?"disabled":"")+'>'+safe(option.meaning_fa||"—")+'</button>'}).join("")+'</div>'+(answer?'<div class="daily-answer-note '+(answer.correct?"is-correct":"is-wrong")+'">'+(answer.correct?"درست است.":"پاسخ درست: "+safe(w.meaning_fa))+'</div><div class="daily-review-controls"><button class="btn-primary" id="dailyReviewNext">'+(daily.reviewIndex<daily.reviewQueue.length-1?"سؤال بعدی":"پایان مرور")+' '+svg("arrow")+'</button></div>':'<div class="daily-review-hint">از بین گزینه‌ها، معنی درست را انتخاب کن.</div>')+'</article>';content.querySelectorAll("[data-daily-option]").forEach(button=>button.onclick=()=>{if(daily.reviewAnswers[daily.reviewIndex])return;const correct=String(button.dataset.dailyOption)===String(w.id);daily.reviewAnswers[daily.reviewIndex]={selectedId:String(button.dataset.dailyOption),correct};if(correct)daily.reviewCorrect++;progress.quizTotal=(progress.quizTotal||0)+1;if(correct)progress.quizCorrect=(progress.quizCorrect||0)+1;persistProgress();saveDaily();renderStats();renderDaily()});if(answer){$("dailyReviewNext").onclick=()=>{if(daily.reviewIndex<daily.reviewQueue.length-1){daily.reviewIndex++;saveDaily();renderDaily()}else{daily.mode="reviewDone";saveDaily();renderDaily()}}}}

function changeView(view){activeView=view;document.querySelectorAll(".view").forEach(el=>el.classList.toggle("active",el.id==="view-"+view));document.querySelectorAll("[data-view]").forEach(el=>el.classList.toggle("active",el.dataset.view===view));const names={home:"داشبورد",learn:"فلش‌کارت‌ها",daily:"یادگیری روزانه",listening:"شنیداری",reading:"خواندن",dictionary:"همه‌ی کلمات",review:"مرور کلمات نشان‌شده",stats:"پیشرفت من","official-exams":"نمونه آزمون‌های رسمی"};$("crumbCurrent").textContent=names[view]||"داشبورد";window.scrollTo({top:0,behavior:"smooth"});if(view==="dictionary")renderDictionary();if(view==="review")renderSaved();if(view==="stats")renderStats();if(view==="daily")renderDaily();if(view==="learn"&&!study.cards.length)startSession("flash")}
$("statsStartLearning").addEventListener("click",()=>changeView("learn"));
function startSession(mode="flash",specified=null){if(!words.length){toast("واژگان هنوز دریافت نشده‌اند.");return}study.mode=mode;let pool=specified||((mode==="saved")?savedWords():dueWords());if(!pool.length)pool=words.filter(w=>!pFor(w).known);if(!pool.length)pool=words.slice();pool=shuffleItems(pool);study.cards=pool.slice(0,mode==="single"?1:12);study.index=0;study.revealed=false;study.correct=0;study.answered=0;study.locked=false;changeView("learn");document.querySelectorAll("[data-study]").forEach(b=>b.classList.toggle("active",b.dataset.study===study.mode));renderStudy()}
function renderStudy(){if(!study.cards.length){$("studyContent").innerHTML='<div class="review-empty"><svg><use href="#i-check"/></svg><h3>برای این مرحله واژه‌ای باقی نمانده است.</h3><p>این بخش را کامل کرده‌ای. برای یادگیری بیشتر از واژه‌نامه یک مسیر تازه انتخاب کن.</p><button class="btn-primary" id="goDict">رفتن به واژه‌نامه</button></div>';$("goDict").onclick=()=>changeView("dictionary");$("studyCounter").textContent="۰ / ۰";$("studyProgress").style.width="100%";return}const w=study.cards[study.index];$("studyCounter").textContent=faNum(study.index+1)+" / "+faNum(study.cards.length);$("studyProgress").style.width=(study.index/study.cards.length*100)+"%";if(study.mode==="quiz"){renderQuiz(w);return}const ex=firstExample(w);$("studyContent").innerHTML='<div class="study-stage"><div class="flashcard '+(study.revealed?"flipped":"")+'" id="flashcard" role="button" tabindex="0" aria-label="'+(study.revealed?"برگرداندن کارت به واژه":"نمایش معنی واژه")+'" aria-pressed="'+(study.revealed?"true":"false")+'"><div class="flash-face flash-front"><span class="flash-chip">'+safe(typeLabel(w.word_type))+(w.record_section==="G"?" · Themen":"")+'</span><div class="flash-word">'+safe(w.word)+'</div><div class="flash-label">واژه‌ی آلمانی</div><div class="flash-hint">برای دیدن معنی، کارت را لمس کن</div><span class="flash-deco" aria-hidden="true">W.</span></div><div class="flash-face flash-back"><span class="flash-chip">BEDEUTUNG · معنی</span><div class="flash-meaning">'+safe(w.meaning_fa||"معنی ثبت نشده")+'</div>'+(ex?'<div class="flash-example">'+safe(ex)+'</div>':'')+'<div class="flash-hint">برای برگشت به واژه، دوباره کارت را لمس کن</div><span class="flash-deco" aria-hidden="true">✓</span></div></div></div><div class="study-controls"><button class="btn-primary known" id="studyKnown">'+svg("check")+' بلدم</button><button class="btn-secondary missed" id="studyMissed">'+svg("close")+' بلد نبودم</button><button class="btn-secondary again" id="studyAgain">'+svg("refresh")+' دوباره مرور کن</button></div>';const toggleCard=()=>{study.revealed=!study.revealed;const card=$("flashcard");card.classList.toggle("flipped",study.revealed);card.setAttribute("aria-pressed",String(study.revealed));card.setAttribute("aria-label",study.revealed?"برگرداندن کارت به واژه":"نمایش معنی واژه")};$("flashcard").onclick=toggleCard;$("flashcard").onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();e.stopPropagation();toggleCard()}};$("studyKnown").onclick=()=>gradeWord(w,"known");$("studyMissed").onclick=()=>gradeWord(w,"again");$("studyAgain").onclick=()=>{study.cards.push(w);nextCard()}}
function buildQuizOptions(w){const targetMeaning=String(w.meaning_fa||"").trim(),pool=shuffleItems(words.filter(x=>String(x.id)!==String(w.id)&&String(x.meaning_fa||"").trim()&&String(x.meaning_fa).trim()!==targetMeaning)),sameType=pool.filter(x=>x.word_type===w.word_type),others=[],usedIds=new Set([String(w.id)]),usedMeanings=new Set(targetMeaning?[targetMeaning]:[]);for(const candidate of [...sameType,...pool]){if(others.length>=3)break;const id=String(candidate.id),meaning=String(candidate.meaning_fa||"").trim();if(usedIds.has(id)||!meaning||usedMeanings.has(meaning))continue;usedIds.add(id);usedMeanings.add(meaning);others.push(candidate)}return shuffleItems([w,...others])}
function renderQuiz(w){const options=buildQuizOptions(w);$("studyContent").innerHTML='<div class="lower-card" style="max-width:700px;margin:auto;padding:28px"><div class="flash-label" style="text-align:center">WAS BEDEUTET DIESES WORT?</div><div class="quiz-question">'+safe(w.word)+'</div><div class="quiz-options">'+options.map((o,i)=>'<button class="quiz-option" data-quiz-id="'+safe(o.id)+'">'+safe(o.meaning_fa||"—")+'</button>').join("")+'</div><div class="study-shortcuts" style="margin-top:18px">معنی درست را انتخاب کن.</div></div><div class="study-controls"><button class="btn-secondary" id="studyAudio">'+svg("volume")+' تلفظ</button></div>';document.querySelectorAll("[data-quiz-id]").forEach(btn=>btn.onclick=()=>{if(study.locked)return;study.locked=true;study.answered++;progress.quizTotal++;const correct=String(w.id)===btn.dataset.quizId;if(correct){study.correct++;progress.quizCorrect++;btn.classList.add("correct");saveWordState(w,{known:true,interval:Math.max(2,pFor(w).interval||0),due:Date.now()+3*86400000,seen:1})}else{btn.classList.add("wrong");const c=[...document.querySelectorAll("[data-quiz-id]")].find(x=>x.dataset.quizId===String(w.id));if(c)c.classList.add("correct");saveWordState(w,{known:false,due:Date.now()+600000,seen:1})}persistProgress();setTimeout(nextCard,950)});$("studyAudio").onclick=()=>speak(w.word)}
function gradeWord(w,grade){const p=pFor(w);let interval=grade==="again"?0:grade==="known"?Math.max(1,p.interval||1):Math.max(4,(p.interval||1)*2);const due=grade==="again"?Date.now()+10*60000:Date.now()+interval*86400000;saveWordState(w,{known:grade==="easy"||grade==="known",interval,repetitions:(p.repetitions||0)+1,due,seen:1});nextCard()}
function nextCard(){if(study.index<study.cards.length-1){study.index++;study.revealed=false;study.locked=false;renderStudy()}else{study.index=study.cards.length;$("studyContent").innerHTML='<div class="review-empty"><svg><use href="#i-spark"/></svg><h3>جلسه به پایان رسید.</h3><p>'+faNum(study.cards.length)+' کارت بررسی شد. پاسخ‌های درست این آزمون: '+(study.mode==="quiz"?faNum(study.correct)+" از "+faNum(study.cards.length):"فلش‌کارت‌ها مرور شدند")+'. استمرار، حافظه را می‌سازد.</p><button class="btn-primary" id="sessionAgain">یک جلسه‌ی دیگر</button> <button class="btn-secondary" id="sessionHome">بازگشت به خانه</button></div>';$("sessionAgain").onclick=()=>startSession(study.mode==="quiz"?"quiz":"flash");$("sessionHome").onclick=()=>changeView("home");$("studyCounter").textContent=faNum(study.cards.length)+" / "+faNum(study.cards.length);$("studyProgress").style.width="100%";progress.sessions++;recordActivity();persistProgress();renderAll()}}
