function renderCommand(query){const q=query.trim().toLocaleLowerCase(),results=(q?words.filter(w=>(wordSearchIndex.get(String(w.id))||"").includes(q)):words.filter(w=>pFor(w).saved||isDue(w))).slice(0,9);$("commandResults").innerHTML=results.length?results.map(w=>'<button class="command-result" data-cmd-id="'+safe(w.id)+'"><span>'+safe(w.word)+'<small>'+safe(w.meaning_fa)+'</small></span>'+svg("arrow")+'</button>').join(""):'<div class="empty">نتیجه‌ای پیدا نشد.</div>';document.querySelectorAll("[data-cmd-id]").forEach(b=>b.onclick=()=>{closeModal("commandOverlay");const w=wordById.get(b.dataset.cmdId);changeView("dictionary");openDetail(w)})}
