function flushPendingProgressForLifecycle(){if(!authUser||!cloudSyncPending)return;clearTimeout(cloudSyncTimer);cloudSyncTimer=null;flushCloudSync().catch(err=>console.warn("Progress remains cached locally until sync can retry.",err))}
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="hidden")flushPendingProgressForLifecycle()});window.addEventListener("pagehide",flushPendingProgressForLifecycle);window.addEventListener("online",()=>{if(authUser&&cloudSyncPending)flushPendingProgressForLifecycle()});
